from pathlib import Path
import argparse,json
import pandas as pd
p=argparse.ArgumentParser();p.add_argument('--root',required=True);R=Path(p.parse_args().root);O=R/'category_top_rules';O.mkdir(exist_ok=True)
t=pd.read_csv(R/'category_screening/top50.csv',dtype={'seed':str,'group_id':str},keep_default_na=False,low_memory=False)
t=t[t.screening_config.eq('strict') & t.increment_policy.eq('increment5pp')].copy()
t['scope']=t.apply(lambda r:'G' if r.method=='G' else 'C'+r.group_id if r.method=='L' else f'R seed={r.seed} / group={r.group_id}',axis=1)
cols=['scope','method','seed','group_id','ranking_length','rank','rule_id','antecedent','consequent','antecedent_name','consequent_name','length','n_baskets','joint_count','antecedent_count','support','confidence','lift','outside_support','outside_confidence','confidence_increment_pp']
t=t[cols];assert t.scope.nunique()==64
for key,z in t.groupby(['scope','ranking_length']):assert z['rank'].tolist()==list(range(1,len(z)+1)) and len(z)<=50
for n in [10,20,50]:t[t['rank'].le(n)].to_csv(O/f'G_L_R_Top{n}.csv',index=False,encoding='utf-8-sig')
s=pd.read_csv(R/'category_screening/scope_summary.csv',dtype={'seed':str,'group_id':str},keep_default_na=False);s=s[s.config.eq('strict')&s.increment.eq('increment5pp')];s['scope']=s.apply(lambda r:'G' if r.method=='G' else 'C'+r.group_id if r.method=='L' else f'R seed={r.seed} / group={r.group_id}',axis=1)
data={'rules':json.loads(t.to_json(orient='records',force_ascii=False)),'counts':s[['scope','length','rules','n_baskets']].to_dict('records')}
intro='taxonomy_v1 子类(l2)规则；严格档：support≥3%、联合及前件次数≥20、confidence≥50%、lift≥1.5。三品类额外要求相对较强单前件confidence增量≥5个百分点；二品类不检查增量。按联合次数↓、confidence↓、lift↓、rule_id↑排序。方向分别占位，未对组合去重。每个范围独立Top-K，不是系统总预算；全部为Discovery开发期结果。'
page='''<!doctype html><html lang="zh"><meta charset="utf-8"><title>品类层 G/L/R Top规则</title><style>body{font:15px "Microsoft YaHei",sans-serif;margin:28px;color:#20334a;background:#f6f8fb}header,.controls{background:white;padding:20px;margin-bottom:16px;border-radius:10px}p{line-height:1.8}select,input{padding:9px;margin:6px}table{border-collapse:collapse;background:white;width:100%}td,th{padding:10px;border-bottom:1px solid #dce4ed;text-align:left}th{background:#253f5f;color:white;position:sticky;top:0}small{color:#647386}td.num{white-space:nowrap}#wrap{overflow:auto}</style><header><h1>品类层 G / L / R Top规则</h1><p>INTRO</p></header><div class="controls"><label>范围<select id="scope"></select></label><label>长度<select id="length"><option value="0">二／三品类混合</option><option value="2">仅二品类</option><option value="3">仅三品类</option></select></label><label>榜单<select id="k"><option>10</option><option>20</option><option>50</option></select></label><label>榜内搜索<input id="q" placeholder="品类中文或代码"></label><p id="info"></p></div><div id="wrap"><table><thead><tr><th>排名</th><th>品类规则</th><th>联合／前件订单数</th><th>Support</th><th>Confidence</th><th>Lift</th><th>三品类增量</th><th>群外Support</th><th>群外Confidence</th></tr></thead><tbody id="body"></tbody></table></div><script>const D=DATA;const el=id=>document.getElementById(id);const esc=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));const pct=x=>x===''||x==null?'—':(Number(x)*100).toFixed(2)+'%';for(const s of [...new Set(D.rules.map(r=>r.scope))]){const o=document.createElement('option');o.value=s;o.textContent=s;el('scope').append(o)}function render(){const s=el('scope').value,l=+el('length').value,k=+el('k').value,q=el('q').value.trim().toLowerCase(),c=D.counts.find(c=>c.scope===s&&c.length===l);const base=D.rules.filter(r=>r.scope===s&&r.ranking_length===l&&r.rank<=k),rows=base.filter(r=>(r.antecedent_name+r.consequent_name+r.antecedent+r.consequent).toLowerCase().includes(q));el('info').textContent=`${s}｜${c.n_baskets}张订单｜${c.rules}条合格规则｜Top${k}实际${base.length}条，搜索后${rows.length}条。`+(base.length<k?'不足不补齐。':'');el('body').innerHTML=rows.map(r=>`<tr><td>${r.rank}</td><td>${esc(r.antecedent_name)}<b> → ${esc(r.consequent_name)}</b><br><small>${esc(r.antecedent)} → ${esc(r.consequent)}</small></td><td>${r.joint_count} / ${r.antecedent_count}</td><td class="num">${pct(r.support)}</td><td class="num">${pct(r.confidence)}</td><td>${Number(r.lift).toFixed(2)}</td><td class="num">${r.length===2?'不适用':Number(r.confidence_increment_pp).toFixed(2)+' pp'}</td><td class="num">${pct(r.outside_support)}</td><td class="num">${pct(r.outside_confidence)}</td></tr>`).join('')}['scope','length','k','q'].forEach(id=>el(id).oninput=render);render();</script></html>'''
(O/'品类层G_L_R_Top规则.html').write_text(page.replace('INTRO',intro).replace('DATA',json.dumps(data,ensure_ascii=False).replace('</','<\\/')),encoding='utf-8')
def md(d):return '| '+' | '.join(d.columns)+' |\n|'+'|'.join(['---']*len(d.columns))+'|\n'+'\n'.join('| '+' | '.join(str(v).replace('|',' / ') for v in row)+' |' for row in d.itertuples(index=False,name=None))
lines=['# 品类层 G/L/R Top榜单',intro,'HTML支持64个范围及三种长度口径；CSV提供Top10/20/50，ranking_length=0表示混合榜，2/3表示分长度榜。随机组逐seed保留，未合并为一个R榜。']
for scope,z in t[t.ranking_length.eq(0)].groupby('scope',sort=False):
 z=z.head(10).copy();z['规则']=z.antecedent_name+' → '+z.consequent_name
 for c in ['support','confidence']:z[c]=z[c].map(lambda v:f'{float(v):.2%}')
 z['lift']=pd.to_numeric(z.lift).round(2);lines.extend([f'## {scope} 混合Top10',md(z[['rank','规则','joint_count','support','confidence','lift']])])
(O/'全部范围Top10.md').write_text('\n\n'.join(lines),encoding='utf-8');print('64 scopes; rows per file:',[(n,int(t['rank'].le(n).sum())) for n in [10,20,50]])
